A: Try this -
def step(string):
    months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    print(f"Input: {string}")
    for month in months:
        if month == string:
            return f"This month has {month} in it."
    else:
        return "Can't find the month in this months list."
    return None

Usage:
